const config = {
  unipileApiBaseUrl: 'https://api40.unipile.com:17046/api/v1',
  unipileApiKey: 'Es8mEoYp.g5m3AwEE5zz17wgEifjbXDAqQpsrUgfUgacoItCOrhc=',
