  defaultDryRun: true,
  testLinkedinUrl: 'https://www.linkedin.com/in/edmundo-c-a06372166/',
  defaultMessage: "Hey {first_name} — quick connect. John here with Transparent eCom. We help regulated brands run compliant ads & scale without getting shut down. Thought it might be relevant.",
  maxConnectionMessageChars: 300,
  requireExplicitSendFlag: true,
  webhookAuthHeaderName: 'x-lt-unipile-key',
  webhookAuthHeaderValue: 'LtUnipile2026',
  ghlApiBaseUrl: 'https://services.leadconnectorhq.com',
  ghlApiKey: 'pit-b278b3ad-96bd-41fb-ba03-9f927039eb28',
  ghlSuccessTag: 'linkedin_connection_requested',
};

