  const raw = clean(input);
  if (!raw) return '';
  if (!/^https?:\/\//i.test(raw)) return decodeURIComponent(raw).replace(/^@/, '').replace(/\/$/, '').trim();
  const withoutScheme = raw.replace(/^https?:\/\//i, '');
  const host = withoutScheme.split('/')[0].split('?')[0].toLowerCase();
  if (!(host === 'linkedin.com' || host.endsWith('.linkedin.com'))) throw new Error('URL host is not linkedin.com');
  const path = withoutScheme.slice(withoutScheme.indexOf('/') >= 0 ? withoutScheme.indexOf('/') : withoutScheme.length).split('?')[0].split('#')[0];
  const parts = path.split('/').filter(Boolean);
  const inIndex = parts.findIndex((p) => p.toLowerCase() === 'in');
  const value = inIndex >= 0 && parts[inIndex + 1] ? parts[inIndex + 1] : parts[parts.length - 1];
