  }
}

const apiBaseUrl = clean(config.unipileApiBaseUrl).replace(/\/$/, '');
const apiKey = clean(config.unipileApiKey);
const ghlApiBaseUrl = clean(config.ghlApiBaseUrl).replace(/\/$/, '');
const ghlApiKey = clean(config.ghlApiKey);
const successTag = clean(config.ghlSuccessTag);
const accountId = clean(body.account_id || body.accountId || config.unipileAccountId);
const contactId = clean(body.contact_id || body.contactId || '');
const linkedinUrl = clean(body.linkedin_url || body.linkedinUrl || body.url || body.profile_url || body.profileUrl || config.testLinkedinUrl);
const identifier = linkedinIdentifier(linkedinUrl);
const maxMessageChars = Math.max(1, Number(config.maxConnectionMessageChars || 300));
const explicitSend = parseBool(body.send, false);
let dryRun = body.dryRun === undefined ? parseBool(config.defaultDryRun, true) : parseBool(body.dryRun, true);
if (explicitSend) dryRun = false;

if (!apiBaseUrl) throw new Error('Missing Unipile API base URL');
if (!apiKey) throw new Error('Missing Unipile API key');
if (!accountId) throw new Error('Missing Unipile account ID');
if (!linkedinUrl) throw new Error('Missing linkedin_url/linkedinUrl/url');
if (!identifier) throw new Error('Could not derive LinkedIn public identifier from URL');
if (!dryRun && config.requireExplicitSendFlag && !explicitSend) {
  throw new Error('Live invite blocked: pass send=true to send a connection request. Dry-run resolves the profile only.');
}

const profileUrl = apiBaseUrl + '/users/' + encodeURIComponent(identifier) + '?account_id=' + encodeURIComponent(accountId);
const profile = await request('GET', profileUrl, undefined, { 'X-API-KEY': apiKey });
const providerId = clean(profile.data?.provider_id || profile.data?.providerId || profile.data?.id || '');
const resolvedFirstName = clean(profile.data?.first_name || profile.data?.firstName || body.first_name || body.firstName || body.contact_first_name || body.contactFirstName || 'there');
const messageTemplate = clean(body.message ?? config.defaultMessage ?? '');
const personalizedMessageRaw = messageTemplate.replace(/\{first_name\}/gi, resolvedFirstName || 'there');
const message = personalizedMessageRaw.length > maxMessageChars ? personalizedMessageRaw.slice(0, maxMessageChars) : personalizedMessageRaw;

const result = {
  ok: profile.ok,
  mode: dryRun ? 'dry_run_resolve_only' : 'live_invite',
  contactId: contactId || null,
  linkedinUrl,
  publicIdentifier: identifier,
  accountId,
  profileResolved: profile.ok,
  providerId: providerId || null,
  profile: profile.ok ? {
    provider: profile.data?.provider || null,
    public_identifier: profile.data?.public_identifier || profile.data?.publicIdentifier || identifier,
    first_name: profile.data?.first_name || profile.data?.firstName || null,
    last_name: profile.data?.last_name || profile.data?.lastName || null,
    headline: profile.data?.headline || null,
  } : null,
  dryRun,
  resolvedFirstName: resolvedFirstName || null,
  messagePreview: message || null,
  messageLength: message.length,
  messageTruncated: personalizedMessageRaw.length > maxMessageChars,
  invite: null,
  tagSync: null,
  error: profile.ok ? null : profile.data,
};

if (!profile.ok || !providerId || dryRun) return [{ json: result }];

const invitePayload = { account_id: accountId, provider_id: providerId };
if (message) invitePayload.message = message;
const invite = await request('POST', apiBaseUrl + '/users/invite', invitePayload, { 'X-API-KEY': apiKey });
result.ok = invite.ok;
result.invite = invite.ok ? invite.data : null;
result.error = invite.ok ? null : invite.data;

if (invite.ok && contactId && ghlApiBaseUrl && ghlApiKey && successTag) {
  const tagRes = await request(
    'POST',
    ghlApiBaseUrl + '/contacts/' + encodeURIComponent(contactId) + '/tags',
    { tags: [successTag] },
    {
      Authorization: 'Bearer ' + ghlApiKey,
      Version: '2021-07-28',
    },
  );
  result.tagSync = {
    attempted: true,
    contactId,
    tag: successTag,
    ok: tagRes.ok,
    error: tagRes.ok ? null : tagRes.data,
  };
} else {
  result.tagSync = {
    attempted: false,
    contactId: contactId || null,
    tag: successTag || null,
    reason: invite.ok ? 'missing_contact_id_or_ghl_config' : 'invite_failed',
  };
}

return [{ json: result }];

